// The iCE40UP5K logic cell, generated by sv/examples/ice40_arch.rs from
// sv/arch/ice40-up5k/record-icebox.txt: the carry and flip-flop statements are
// icebox_vlog's own (run as a black box), with its nets named by role.
module ice40up5k_logic_cell #(
  parameter logic [15:0] LUT_INIT = 16'h0000,
  parameter bit DFF_ENABLE = 1'b0,
  parameter bit SET_NORESET = 1'b0,
  parameter bit ASYNC_SR = 1'b0,
  parameter bit NEG_CLK = 1'b0
) (
  input logic in_0, in_1, in_2, in_3, ci, clk, cen, sr,
  output logic out, co
);
  logic lout, q;
  // LUT index in_0 + 2 in_1 + 4 in_2 + 8 in_3 (logic_cell.lut_index).
  assign lout = LUT_INIT[{in_3, in_2, in_1, in_0}];
  // CarryEnable
  assign co = (in_1 & in_2) | ((in_1 | in_2) & ci);
  generate
    if (SET_NORESET == 1'b0 && ASYNC_SR == 1'b0 && NEG_CLK == 1'b0) begin : ff_000
      always @(posedge clk) if (cen) q <= sr ? 1'b0 : lout;
    end
    else if (SET_NORESET == 1'b1 && ASYNC_SR == 1'b0 && NEG_CLK == 1'b0) begin : ff_100
      always @(posedge clk) if (cen) q <= sr ? 1'b1 : lout;
    end
    else if (SET_NORESET == 1'b0 && ASYNC_SR == 1'b1 && NEG_CLK == 1'b0) begin : ff_010
      always @(posedge clk, posedge sr) if (sr) q <= 1'b0; else if (cen) q <= lout;
    end
    else if (SET_NORESET == 1'b1 && ASYNC_SR == 1'b1 && NEG_CLK == 1'b0) begin : ff_110
      always @(posedge clk, posedge sr) if (sr) q <= 1'b1; else if (cen) q <= lout;
    end
    else if (SET_NORESET == 1'b0 && ASYNC_SR == 1'b0 && NEG_CLK == 1'b1) begin : ff_001
      always @(negedge clk) if (cen) q <= sr ? 1'b0 : lout;
    end
    else if (SET_NORESET == 1'b1 && ASYNC_SR == 1'b0 && NEG_CLK == 1'b1) begin : ff_101
      always @(negedge clk) if (cen) q <= sr ? 1'b1 : lout;
    end
    else if (SET_NORESET == 1'b0 && ASYNC_SR == 1'b1 && NEG_CLK == 1'b1) begin : ff_011
      always @(negedge clk, posedge sr) if (sr) q <= 1'b0; else if (cen) q <= lout;
    end
    else if (SET_NORESET == 1'b1 && ASYNC_SR == 1'b1 && NEG_CLK == 1'b1) begin : ff_111
      always @(negedge clk, posedge sr) if (sr) q <= 1'b1; else if (cen) q <= lout;
    end
  endgenerate
  // DffEnable, and without it: assign out = lout;
  assign out = DFF_ENABLE ? q : lout;
endmodule
